public boolean compatibleWithBlock(TFMLogicBlock _block)
{
    return classIdGet(_block) == classNum(MwmsLogicBlockMoveInvent);
}

public void modifyDataBeforePost(TFMLogicBlock _block)
{
    MwmsLogicBlockMoveInvent moveBlock = _block;
    InventJournalTrans          trs;
    InventJournalTable          tbl;

    if (moveBlock.getInventDimIssue().inventDimId != moveBlock.getInventDimReceipt().inventDimId)
    {
        return;
    }
    ttsbegin;
    trs = moveBlock.getInventJournalTrans();
    trs.selectForUpdate(true);
    trs.doDelete();
    tbl = moveBlock.getinventJournalTable();
    tbl.selectForUpdate(true);
    tbl.doDelete();
    ttscommit;
    moveBlock.getinventJournalTable().reread();

}
